// 캐릭터 정보를 담는 구조체
struct CharInfo
{
    int  charNumber;   // 4바이트 그릇
    int  level;        // 4바이트 그릇
    int  hp;           // 4바이트 그릇
};

// 이 구조체의 크기는?  4 + 4 + 4 = 12바이트
// sizeof(CharInfo) 라고 쓰면 12가 나온다.
//
// (사실 컴파일러가 멤버 사이에 빈칸을 넣어 더 커질 수도 있어.
//  지금은 빈칸이 없는 경우로 보자. 맨 끝에서 다시 얘기할게.)

// 모든 메시지가 물려받는 공통 머리
struct 공통헤더
{
    WORD   번호;        // 2바이트
    WORD   보조정보;    // 2바이트
    DWORD  순번;        // 4바이트
    DWORD  여분;        // 4바이트
};                      // 합쳐서 12바이트

// 실제 메시지 = 공통헤더를 물려받고, 내 멤버를 뒤에 붙인다
struct 캐릭터로드구조체 : public 공통헤더
{
    int  charNumber;    // 4
    int  level;         // 4
    int  hp;            // 4
};

// 메모리에서의 모양:
//   [번호][보조][순번][여분][charNumber][level][hp]
//   └───── 헤더 12 ─────┘└───── 본문 12 ─────┘
//
// sizeof(캐릭터로드구조체) = 24   ← 헤더가 이미 안에 있으니 한 번에 나온다

// 크기 표 = 그냥 배열이다
DWORD  msgSizeTable[4096];   // 4096칸 × 4바이트 = 16KB
                             // (실제론 보내는 쪽/받는 쪽 2개라 32KB)
                             // 처음엔 전부 0

// 서버 켜질 때 등록 — 200번 반복
msgSizeTable[2003] = sizeof(캐릭터로드구조체);   // 예: 24 (헤더 12 + 본문 12)
msgSizeTable[2004] = sizeof(캐릭터응답구조체);   // 예: 512

// 받을 때 조회
DWORD size = msgSizeTable[ 도착한번호 ];
// 등록 안 된 번호면?  →  0 이 나온다
